var o=[{title:`Elabora un presupuesto de tiempo`,text:`El tiempo total de un entrenamiento incluye prepararte, calentar, montar cada ejercicio, las series de trabajo, los descansos, el paso de un ejercicio a otro y una vuelta a la calma opcional. En una sesión de fuerza, el tiempo que pasas levantando de verdad suele ser una parte pequeña del total. Tres series de 40 segundos con dos minutos de descanso entre ellas llevan unos seis minutos para ese ejercicio, antes de cualquier cambio de equipamiento.`},{title:`Una estimación sencilla`,text:`Suma el tiempo de calentamiento, la duración de cada serie de trabajo, los descansos entre series y los cambios. Por ejemplo, cuatro ejercicios × tres series de 40 segundos son ocho minutos de trabajo real. Si cada ejercicio tiene dos descansos de 90 segundos, suma doce minutos. Un calentamiento de seis minutos y unos ocho minutos de preparación y cambios llevan la sesión a unos 34 minutos. Los descansos más largos para el trabajo pesado pueden cambiar mucho el total.`},{title:`Opción de 20 minutos`,text:`Mantén corto el calentamiento, elige dos o tres patrones de movimiento principales y haz unas pocas buenas series de cada uno. Combinar un empuje y un tirón puede ahorrar tiempo de cambio cuando tu equipamiento y tu técnica lo permiten, pero no recortes tanto el descanso que pierdas el objetivo principal de fuerza.`},{title:`Opciones de 30 a 45 minutos`,text:`Añade una bisagra o una zancada, un ejercicio de core o series extra para tu patrón prioritario. Si tu objetivo es la forma física general, usa el tiempo restante para trabajo aeróbico. No necesitas llenar cada minuto libre con «finishers».`},{title:`Protege tus prioridades`,text:`Cuando falta tiempo, elimina primero los ejercicios accesorios de baja prioridad. Conserva el calentamiento y no apresures tus levantamientos compuestos pesados. Si todo el programa se pasa de tiempo una y otra vez, planifica menos para cada sesión en lugar de contar con un ritmo que no puedes mantener.`},{title:`Cómo usar TrainUp`,text:`Define en Perfil la duración de la sesión con los minutos que realmente tienes. Si terminas el trabajo principal con buena técnica, la sesión fue un éxito, aunque te hayas saltado los extras opcionales.`}];var s=[{label:`Declaración de posición del ACSM de 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`CDC: planificación práctica de la actividad`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`}];var i={sections:o,sources:s};export{i as default,o as sections,s as sources};